en-to-zh.css:
.card {
  text-align: center;
  font-size: 17px;
  line-height: 1.6;
}
.uc-ask {
  margin-bottom: 14px;
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  opacity: 0.55;
}
.uc-simp {
  font-family: var(--han, "Noto Sans SC", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif);
  font-size: 46px;
  font-weight: 400;
  line-height: 1.15;
}
.uc-trad {
  font-family: var(--han, "Noto Sans SC", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif);
  margin-top: 8px;
  font-size: 34px;
  font-weight: 400;
  line-height: 1.25;
  opacity: 0.5;
}
.uc-pinyin {
  margin-top: 12px;
  font-size: 21px;
  letter-spacing: 0.01em;
  color: var(--zh, #C8453C);
}
.uc-zhuyin {
  font-family: var(--han, "Noto Sans SC", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif);
  margin-top: 5px;
  font-size: 17px;
  letter-spacing: 0.06em;
  opacity: 0.72;
}
.uc-mw {
  margin-top: 12px;
  font-size: 15px;
  line-height: 1.5;
}
.uc-mwlab {
  margin-right: 8px;
  font-size: 9.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  opacity: 0.5;
}
.uc-mwi + .uc-mwi {
  margin-left: 12px;
}
.uc-mwc {
  font-family: var(--han, "Noto Sans SC", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif);
  font-weight: 400;
}
.uc-mwt {
  margin-left: 4px;
  opacity: 0.5;
}
.uc-mwp {
  margin-left: 6px;
  opacity: 0.75;
}
.uc-field {
  display: block;
  width: fit-content;
  max-width: 100%;
  margin: 14px auto 0;
  padding: 11px 15px;
  border: 1px solid var(--rule, rgba(0,0,0,0.12));
  border-radius: 11px;
  text-align: left;
  background: var(--paper-2, rgba(0,0,0,0.05));
  background: color-mix(in srgb, var(--paper-2, #EFEDE6) 58%, var(--card, #FFFFFF));
}
.uc-sense {
  line-height: 1.6;
}
.uc-pos {
  margin-right: 0.4em;
  font-size: 0.78em;
  font-style: italic;
  color: var(--ink-faint, #6C6A63);
}
.uc-chars {
  display: block;
  width: fit-content;
  max-width: 100%;
  margin: 14px auto 0;
  text-align: left;
}
.uc-ch {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 4px 0;
  font-size: 13.5px;
}
.uc-ch + .uc-ch:not(.uc-chtr) {
  border-top: 1px solid var(--rule, rgba(0,0,0,0.10));
}
.uc-chtr {
  padding-top: 0;
  opacity: 0.5;
}
.uc-chc {
  font-family: var(--han, "Noto Sans SC", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif);
  font-weight: 400;
  font-size: 22px;
  line-height: 1.1;
  min-width: 26px;
}
.uc-chps {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.uc-pt {
  display: flex;
  align-items: baseline;
  gap: 7px;
}
.uc-pt b {
  font-family: var(--han, "Noto Sans SC", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif);
  font-weight: 400;
  font-size: 16px;
  min-width: 19px;
}
.uc-ptp {
  min-width: 44px;
}
.uc-pt i {
  font-style: normal;
  opacity: 0.6;
}
.uc-solo {
  font-style: italic;
  opacity: 0.6;
}
.uc-ex {
  display: block;
  width: fit-content;
  max-width: 100%;
  margin: 14px auto 0;
  text-align: center;
}
.uc-ex > summary {
  cursor: pointer;
  list-style: none;
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  opacity: 0.6;
}
.uc-ex > summary::-webkit-details-marker {
  display: none;
}
.uc-ex > summary::after {
  content: " ▾";
}
.uc-ex[open] > summary::after {
  content: " ▴";
}
.uc-exs {
  margin-top: 9px;
  padding: 11px 14px;
  border: 1px solid var(--rule, rgba(0,0,0,0.12));
  border-radius: 11px;
  background: var(--paper-2, rgba(0,0,0,0.05));
}
.uc-exi + .uc-exi {
  margin-top: 10px;
  padding-top: 10px;
  border-top: 1px solid var(--rule, rgba(0,0,0,0.10));
}
.uc-exst {
  margin-bottom: 4px;
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.09em;
  line-height: 1.45;
  text-transform: uppercase;
  color: var(--ink-faint, #6C6A63);
}
.uc-exst b {
  font-weight: 600;
  color: var(--zh, #C8453C);
}
.uc-exsay {
  margin-right: 7px;
  font-size: 12px;
  vertical-align: 0.08em;
}
.uc-tts {
  background: var(--paper, #F6F5F1);
  border-color: var(--paper-2, rgba(0,0,0,0.12));
}
.uc-exz {
  font-family: var(--han, "Noto Sans SC", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif);
  font-weight: 400;
  font-size: 18px;
  line-height: 1.5;
}
.uc-exz b {
  font-weight: 400;
  color: var(--zh, #C8453C);
}
.uc-exe {
  margin-top: 1px;
  font-size: 14px;
  opacity: 0.75;
}
.uc-sense + .uc-sense {
  margin-top: 2px;
}
hr {
  margin: 18px 0;
  border: 0;
  border-top: 1px solid currentColor;
  opacity: 0.18;
}
.uc-sense {
  font-size: 18px;
}
